 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            comps.append((color, cells))
    # Pack objects toward the right, settling rightmost objects first.
    comps.sort(key=lambda z: max(c for _, c in z[1]), reverse=True)
    out = [[0]*w for _ in range(h)]
    for color, cells in comps:
        shift = 0
        while True:
            ns = shift + 1
            if any(c + ns >= w or out[r][c+ns] != 0 for r,c in cells):
                break
            shift = ns
        for r,c in cells:
            out[r][c+shift] = color
    return out
